import sys

MOD = 998244353

def factor(x):
    res = {}
    d = 2
    while d * d <= x:
        while x % d == 0:
            res[d] = res.get(d, 0) + 1
            x //= d
        d += 1
    if x > 1:
        res[x] = res.get(x, 0) + 1
    return res

def contribution(p, exponents):
    total = sum(exponents)
    # The extra space covers the largest possible normalization shift d*t.
    powers = [1] * (total + 10001)
    for i in range(1, len(powers)):
        powers[i] = powers[i - 1] * p % MOD

    # h is the current height above the minimum of the path so far.
    dp = {0: 1}
    prior_count = 1
    for e in exponents:
        nxt = {}
        steps = (0,) if e == 0 else (e, -e)
        for h, value in dp.items():
            for step in steps:
                raw = h + step
                if raw >= 0:
                    nh = raw
                    multiplier = powers[raw]
                else:
                    # The new minimum is -raw below the old one; all
                    # prior entries are shifted upward by that amount.
                    nh = 0
                    multiplier = powers[(-raw) * prior_count]
                nxt[nh] = (nxt.get(nh, 0) + value * multiplier) % MOD
        dp = nxt
        prior_count += 1
    return sum(dp.values()) % MOD

data = list(map(int, sys.stdin.buffer.read().split()))
n = data[0]
arr = data[1:]
factors = [factor(x) for x in arr]
primes = set()
for f in factors:
    primes.update(f)

answer = 1
for p in primes:
    exponents = [f.get(p, 0) for f in factors]
    answer = answer * contribution(p, exponents) % MOD
print(answer)

