import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:1 + n]
    limit = max(values)

    smallest = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if smallest[p] == p:
            for v in range(p * p, limit + 1, p):
                if smallest[v] == v:
                    smallest[v] = p

    result = 0
    for value in values:
        factors = 0
        while value > 1:
            value //= smallest[value]
            factors += 1
        result ^= factors

    print("Anna" if result else "Bruno")


if __name__ == "__main__":
    main()

