import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    edges = [(next(it)-1, next(it)-1, next(it)) for _ in range(m)]
    queries = []
    closed = [False] * m
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            e = next(it) - 1
            queries.append((1, e))
            closed[e] = True
        else:
            queries.append((2, next(it)-1, next(it)-1))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for e, (u, v, w) in enumerate(edges):
        if not closed[e] and w < dist[u][v]:
            dist[u][v] = dist[v][u] = w

    # Floyd-Warshall, using symmetry to process only half the matrix.
    for k in range(n):
        dk = dist[k]
        for i in range(n):
            dik = dist[i][k]
            di = dist[i]
            for j in range(i, n):
                cand = dik + dk[j]
                if cand < di[j]:
                    di[j] = cand
                    dist[j][i] = cand

    answers = []
    # Reverse time: a closure becomes an edge insertion.
    for query in reversed(queries):
        if query[0] == 2:
            value = dist[query[1]][query[2]]
            answers.append(str(value if value < INF else -1))
        else:
            u, v, w = edges[query[1]]
            du = [dist[i][u] for i in range(n)]
            dv = [dist[i][v] for i in range(n)]
            ru = dist[u][:]
            rv = dist[v][:]
            for i in range(n):
                di = dist[i]
                a, b = du[i], dv[i]
                for j in range(i, n):
                    cand = min(a + w + rv[j], b + w + ru[j])
                    if cand < di[j]:
                        di[j] = cand
                        dist[j][i] = cand

    sys.stdout.write("\n".join(reversed(answers)))

if __name__ == "__main__":
    main()

