import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    vals = data[2:]

    def feasible(k):
        total = 0
        for i in range(n):
            a, p, b, q = vals[4*i:4*i+4]
            best = ((k + a - 1) // a) * p
            # For each residue of the number of S machines modulo b,
            # the cost is linear between the points where the required
            # number of T machines changes, so only the endpoints matter.
            for r in range(b):
                z = k - a * r
                if z <= 0:
                    candidates = (0,)
                else:
                    u = z // (a * b)
                    candidates = (0, u, u + 1)
                for t in candidates:
                    x = r + b * t
                    rem = k - a * x
                    y = 0 if rem <= 0 else (rem + b - 1) // b
                    cost = x * p + y * q
                    if cost < best:
                        best = cost
            total += best
            if total > budget:
                return False
        return True

    lo, hi = 0, 1_000_000_001
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)

if __name__ == '__main__':
    main()

