class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        fact = [1] * (length + 1)
        for i in range(1, length + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (length + 1)
        inv_fact[length] = pow(fact[length], MOD - 2, MOD)
        for i in range(length, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def choose(n, r):
            if r < 0 or r > n:
                return 0
            return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

        good = [False] * (length + 1)
        for count in range(1, length + 1):
            value = count
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[count] = steps <= k - 1

        answer = 0
        prefix_ones = 0
        for i, bit in enumerate(s):
            if bit == '1':
                remaining = length - i - 1
                for total_ones in range(1, length + 1):
                    needed = total_ones - prefix_ones
                    if good[total_ones] and 0 <= needed <= remaining:
                        answer = (answer + choose(remaining, needed)) % MOD
                prefix_ones += 1

        return answer

