        MOD = 10**9 + 7
        L = len(s)
        comb = [[0]*(L+1) for _ in range(L+1)]
        comb[0][0] = 1
        for i in range(1, L+1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD
        good = [False]*(L+1)
        for m in range(1, L+1):
