import random

def alg(U,D,X):
 n=len(U)
 def ok(h):
  lo=max(0,h-D[0]);hi=min(U[0],h)
  for i in range(1,n):
   l=max(0,h-D[i]);r=min(U[i],h)
   lo=max(l,lo-X);hi=min(r,hi+X)
   if lo>hi:return False
  return lo<=hi
