    seen = bytearray(H * W)
    seen[start] = 1
    strength = values[start]
    heap = []

    def add(v):
        if not seen[v]:
            heapq.heappush(heap, (values[v], v))

    if P > 0:
        add(start - W)
    if P + 1 < H:
        add(start + W)
    if Q > 0:
        add(start - 1)
    if Q + 1 < W:
        add(start + 1)

    while heap:
        value, v = heapq.heappop(heap)
        if seen[v]:
