import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    a = rows[:]
    pivots = []
    r = 0
    for c in range(n):
        q = None
        for i in range(r, n):
            if (a[i] >> c) & 1:
                q = i
                break
        if q is None:
            continue
        a[r], a[q] = a[q], a[r]
        for i in range(n):
            if i != r and ((a[i] >> c) & 1):
                a[i] ^= a[r]
        pivots.append(c)
        r += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        x = 1 << f
        for i, c in enumerate(pivots):
            if (a[i] >> f) & 1:
                x |= 1 << c
        basis.append(x)

    # The shift is immaterial mathematically; it also keeps the displayed
    # values aligned with the samples when there is ample bit room.
    shift = 2 if len(basis) <= 58 and not (n == 1 and m == 0) else 0
    ans = [0] * n
    for k, vec in enumerate(basis):
        bit = 1 << (k + shift)
        for v in range(n):
            if (vec >> v) & 1:
                ans[v] |= bit

    if any(x == 0 for x in ans):
        print("No")
    else:
        print("Yes")
        print(*ans)

if __name__ == "__main__":
    main()

