from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = 10**15 + 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        odd_left = (n + 1) // 2
        even_left = n // 2
        used = [False] * (n + 1)
        result = []
        previous_parity = None

        for position in range(n):
            found = False
            for value in range(1, n + 1):
                parity = value & 1
                if used[value] or (previous_parity is not None and parity == previous_parity):
                    continue

                odd = odd_left - parity
                even = even_left - (1 - parity)
                remaining = n - position - 1

                if remaining == 0:
                    count = 1
                else:
                    next_parity = 1 - parity
                    needed_odd = ((remaining + 1) // 2
                                  if next_parity == 1 else remaining // 2)
                    needed_even = (remaining // 2
                                   if next_parity == 1 else (remaining + 1) // 2)
                    if odd == needed_odd and even == needed_even:
                        count = min(cap, fact[odd] * fact[even])
                    else:
                        count = 0

                if k > count:
                    k -= count
                    continue

                used[value] = True
                result.append(value)
                odd_left -= parity
                even_left -= 1 - parity
                previous_parity = parity
                found = True
                break

            if not found:
                return []

        return result

