class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half_len = (n + 1) // 2

        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        # Each half digit contributes its place value and, except for
        # the middle digit, the value of its mirrored place.
        weights = []
        for i in range(half_len):
            w = powers[n - 1 - i]
            if i != n - 1 - i:
                w = (w + powers[i]) % k
            weights.append(w)

        # suffix[i] is a bit mask of all residues obtainable from
        # positions i and later.
        suffix = [0] * (half_len + 1)
        suffix[half_len] = 1  # residue zero
        for i in range(half_len - 1, -1, -1):
            w = weights[i]
            following = suffix[i + 1]
            mask = 0
            for digit in range(10):
                shift = digit * w % k
                for residue in range(k):
                    if (following >> residue) & 1:
                        mask |= 1 << ((residue + shift) % k)
            suffix[i] = mask

        chosen = []
        current = 0
        for i, w in enumerate(weights):
            low = 1 if i == 0 else 0
            for digit in range(9, low - 1, -1):
                new_residue = (current + digit * w) % k
                needed = (-new_residue) % k
                if (suffix[i + 1] >> needed) & 1:
                    chosen.append(str(digit))
                    current = new_residue
                    break

        first_half = ''.join(chosen)
        if n % 2:
            return first_half + first_half[-2::-1]
        return first_half + first_half[::-1]

