from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        from array import array

        n = len(nums)
        next_greater = [n] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                next_greater[stack.pop()] = i
            stack.append(i)

        levels = n.bit_length()
        jump = [array('i', next_greater)]
        weight = [array('q',
                        (nums[i] * (next_greater[i] - i) for i in range(n)))]

        for _ in range(1, levels):
            prev_jump = jump[-1]
            prev_weight = weight[-1]
            cur_jump = array('i', [0]) * n
            cur_weight = array('q', [0]) * n
            for i in range(n):
                mid = prev_jump[i]
                if mid < n:
                    cur_jump[i] = prev_jump[mid]
                    cur_weight[i] = prev_weight[i] + prev_weight[mid]
                else:
                    cur_jump[i] = n
                    cur_weight[i] = prev_weight[i]
            jump.append(cur_jump)
            weight.append(cur_weight)

        prefix = [0]
        for x in nums:
            prefix.append(prefix[-1] + x)

        def required(left: int, right: int) -> int:
            pos = left
            total_target = 0
            for level in range(levels - 1, -1, -1):
                after = jump[level][pos]
                if after <= right:
                    total_target += weight[level][pos]
                    pos = after
            total_target += nums[pos] * (right + 1 - pos)
            return total_target - (prefix[right + 1] - prefix[left])

        answer = 0
        left = 0
        for right in range(n):
            while required(left, right) > k:
                left += 1
            answer += right - left + 1
        return answer

