        st=[]
        for i,x in enumerate(nums):
            while st and nums[st[-1]]<x:
                ng[st.pop()]=i
            st.append(i)
        LOG=n.bit_length()
        ep=[array('i',ng)]
        wt=[array('q',(nums[i]*(ng[i]-i) for i in range(n)))]
        for z in range(1,LOG):
            pe,pw=ep[-1],wt[-1]
            ce=array('i',[0])*n
            cw=array('q',[0])*n
            for i in range(n):
                m=pe[i]
                ce[i]=pe[m] if m<n else n
                cw[i]=pw[i]+(pw[m] if m<n else 0)
            ep.append(ce); wt.append(cw)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
