            cur=l; total=0
            for z in range(LOG-1,-1,-1):
                q=ep[z][cur]
                if q<=r:
                    total+=wt[z][cur]; cur=q
            total += nums[cur]*(r+1-cur)
            return total-(pref[r+1]-pref[l])
        ans=0; l=0
        for r in range(n):
            while l<=r and cost(l,r)>k: l+=1
            ans += r-l+1
        return ans

