class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0]*26
        for ch in s:
            cnt[ord(ch)-97] += 1
        n = len(s)
        cand = {1}
        cand.update(x for x in cnt if x)
        # Optima which are averages of groups of letters are also covered by
        # these (the alphabet is small; include the useful global averages).
        for k in range(1,27):
            cand.add(max(1, n//k))
            cand.add(max(1, (n+k-1)//k))
        INF = 10**9
        ans = n
        for f in cand:
            d0 = {0: 0}       # no letter selected yet
            d1 = {}           # at least one selected
            for c in cnt:
                nd0 = {}
                nd1 = {}
                for ca,v in d0.items():
                    x=ca+c
                    if v < nd0.get(x,INF): nd0[x]=v
                    nc=max(0,x-f); z=v+ca+max(0,f-x)
                    if z < nd1.get(nc,INF): nd1[nc]=z
                for ca,v in d1.items():
                    x=ca+c
                    if v < nd1.get(x,INF): nd1[x]=v
                    nc=max(0,x-f); z=v+ca+max(0,f-x)
                    if z < nd1.get(nc,INF): nd1[nc]=z
                d0,d1=nd0,nd1
            best=min(v+ca for ca,v in d1.items())
            if best<ans: ans=best
        return ans

