import sys
from functools import lru_cache

sys.setrecursionlimit(1_000_000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, l = data[:3]
    values = data[3:]
    lower = []
    for x in values:
        mask = 0
        for j, y in enumerate(values):
            if y < x:
                mask |= 1 << j
        lower.append(mask)

    @lru_cache(None)
    def winning(takahashi, aoki, table, turn):
        hand = takahashi if turn == 0 else aoki
        if not hand:
            return False
        while hand:
            bit = hand & -hand
            hand -= bit
            i = bit.bit_length() - 1
            nt = takahashi & ~bit if turn == 0 else takahashi
            na = aoki if turn == 0 else aoki & ~bit
            new_table = table | bit

            # The player may leave all cards on the table.
            if not winning(nt, na, new_table, 1 - turn):
                return True

            choices = table & lower[i]
            while choices:
                card = choices & -choices
                choices -= card
                if turn == 0:
                    if not winning(nt | card, na, new_table ^ card, 1):
                        return True
                else:
                    if not winning(nt, na | card, new_table ^ card, 0):
                        return True
        return False

    t0 = (1 << n) - 1
    a0 = ((1 << m) - 1) << n
    table0 = ((1 << l) - 1) << (n + m)
    print("Takahashi" if winning(t0, a0, table0, 0) else "Aoki")

if __name__ == "__main__":
    main()

