import sys
import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    g = [[] for _ in range(n)]
    q = 1
    for _ in range(n - 1):
        u, v, w = data[q] - 1, data[q + 1] - 1, data[q + 2]
        q += 3
        g[u].append((v, w))
        g[v].append((u, w))

    parent = [-1] * n
    order = [0]
    for v in order:
        for u, w in g[v]:
            if u != parent[v]:
                parent[u] = v
                order.append(u)

    heaps = [None] * n
    for v in reversed(order):
        h = []                         # negative marginal values
        for u, w in g[v]:
            if parent[u] != v:
                continue
            x = heaps[u]
            if x:
                # The first marginal of this child includes the connecting edge.
                x[0] -= w
            else:
                # A child which is a leaf contributes one marginal: this edge.
                x = [-w]
            # Meld smaller heaps into the larger one.
            if len(x) > len(h):
                h, x = x, h
            for z in x:
                heapq.heappush(h, z)
        heaps[v] = h

    gains = sorted((-x for x in heaps[0]), reverse=True)
    total = 0
    ans = []
    for k in range(1, n + 1):
        if k <= len(gains):
            total += gains[k - 1]
        ans.append(str(2 * total))
    sys.stdout.write("\n".join(ans))


if __name__ == "__main__":
    main()

