from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        tokens = [part for part in parts if part]
        if not tokens:
            return 0

        def occurrences(pattern):
            m = len(pattern)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        positions = [occurrences(token) for token in tokens]
        if any(not items for items in positions):
            return -1

        answer = len(s) + 1
        first_length = len(tokens[0])
        for start in positions[0]:
            end = start + first_length
            for k in range(1, len(tokens)):
                index = bisect_left(positions[k], end)
                if index == len(positions[k]):
                    break
                end = positions[k][index] + len(tokens[k])
            else:
                answer = min(answer, end - start)

        return -1 if answer == len(s) + 1 else answer

