    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    graph = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        graph[x].append((y, z))
        graph[y].append((x, z))

    seen = [False] * n
    potential = [0] * n
    answer = [0] * n

    for start in range(n):
        if seen[start]:
            continue
        seen[start] = True
        potential[start] = 0
        stack = [start]
        component = []

        while stack:
            u = stack.pop()
            component.append(u)
            for v, z in graph[u]:
                expected = potential[u] ^ z
                if not seen[v]:
                    seen[v] = True
                    potential[v] = expected
                    stack.append(v)
                elif potential[v] != expected:
                    print(-1)
                    return

        shift = 0
        size = len(component)
        for bit in range(30):
            ones = 0
            mask = 1 << bit
            for u in component:
                if potential[u] & mask:
                    ones += 1
            if ones * 2 > size:
                shift |= mask
        for u in component:
            answer[u] = potential[u] ^ shift

    print(*answer)

