class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        stack = [0]
        order = []
        while stack:
            x = stack.pop()
            order.append(x)
            stack.extend(children[x])
        postorder = order[::-1]

        position = [0] * n
        for i, x in enumerate(postorder):
            position[x] = i

        size = [1] * n
        for x in postorder:
            if x != 0:
                size[parent[x]] += size[x]

        sequence = ''.join(s[x] for x in postorder)
        transformed = '^#' + '#'.join(sequence) + '#$'
        radius = [0] * len(transformed)
        center = right = 0
        for i in range(1, len(transformed) - 1):
            mirror = 2 * center - i
            if i < right:
                radius[i] = min(right - i, radius[mirror])
            while transformed[i + radius[i] + 1] == transformed[i - radius[i] - 1]:
                radius[i] += 1
            if i + radius[i] > right:
                center, right = i, i + radius[i]

        answer = []
        for x in range(n):
            r = position[x]
            l = r - size[x] + 1
            # In the transformed string, this is the center of [l, r].
            answer.append(radius[l + r + 2] >= r - l)
        return answer

