import sys, heapq
from collections import deque

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m = next(it), next(it)
    s, t = next(it)-1, next(it)-1
    z = 2*n
    g = [[] for _ in range(z)]

    def add(a, b, cap, cost):
        g[a].append([b, cap, cost, len(g[b])])
        g[b].append([a, 0, -cost, len(g[a])-1])

    for v in range(n):
        add(2*v, 2*v+1, 2 if v == s or v == t else 1, 0)
    for _ in range(m):
        u, v = next(it)-1, next(it)-1
        add(2*u+1, 2*v, 1, 1)
        add(2*v+1, 2*u, 1, 1)

    source, sink = 2*s, 2*t+1
    INF = 10**9
    potential = [INF] * z
    potential[source] = 0
    q = deque([source])
    queued = [False] * z
    queued[source] = True
    while q:
        x = q.popleft()
        queued[x] = False
        for y, cap, cost, rev in g[x]:
            if cap and potential[y] > potential[x] + cost:
                potential[y] = potential[x] + cost
                if not queued[y]:
                    queued[y] = True
                    q.append(y)
    if potential[sink] == INF:
        print(-1)
        return

    answer = 0
    for round_no in range(2):
        dist = [INF] * z
        parent = [None] * z
        dist[source] = 0
        if round_no == 0:
            q = deque([source])
            while q:
                x = q.popleft()
                for i, (y, cap, cost, rev) in enumerate(g[x]):
                    if cap and dist[y] > dist[x] + cost:
                        dist[y] = dist[x] + cost
                        parent[y] = (x, i)
                        (q.appendleft(y) if cost == 0 else q.append(y))
        else:
            q = [(0, source)]
            while q:
                d, x = heapq.heappop(q)
                if d != dist[x]:
                    continue
                for i, (y, cap, cost, rev) in enumerate(g[x]):
                    if cap:
                        nd = d + cost + potential[x] - potential[y]
                        if nd < dist[y]:
                            dist[y] = nd
                            parent[y] = (x, i)
                            heapq.heappush(q, (nd, y))
            for v in range(z):
                if dist[v] < INF:
                    potential[v] += dist[v]
        if dist[sink] == INF:
            print(-1)
            return
        v = sink
        while v != source:
            x, i = parent[v]
            edge = g[x][i]
            answer += edge[2]
            edge[1] -= 1
            g[v][edge[3]][1] += 1
            v = x
    print(answer)

solve()

