    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = 10**30
        mins = [INF] * k
        mins[0] = 0
        pref = 0
        ans = -INF
        for i, x in enumerate(nums, 1):
            pref += x
            r = i % k
            if mins[r] != INF:
                ans = max(ans, pref - mins[r])
            if pref < mins[r]:
                mins[r] = pref
        return ans

