import sys

def main():
    input = sys.stdin.readline
    n, q = map(int, input().split())
    s = list(input().strip())

    def is_abc(i):
        return i >= 0 and i + 2 < n and s[i] == 'A' and s[i + 1] == 'B' and s[i + 2] == 'C'

    count = sum(is_abc(i) for i in range(n - 2))
    output = []

    for _ in range(q):
        x, c = input().split()
        x = int(x) - 1

        # Only substrings starting at x-2, x-1, or x can be affected.
        lo = max(0, x - 2)
        hi = min(n - 3, x)
        for i in range(lo, hi + 1):
            if is_abc(i):
                count -= 1

        s[x] = c

        for i in range(lo, hi + 1):
            if is_abc(i):
                count += 1
        output.append(str(count))

    sys.stdout.write('\n'.join(output))

if __name__ == '__main__':
    main()

