class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        MOD = 1_000_000_007
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        for _ in range(t):
            nxt = [0] * 26
            z_count = counts[25]
            nxt[0] = z_count
            nxt[1] = (counts[0] + z_count) % MOD
            for i in range(1, 25):
                nxt[i + 1] = counts[i]
            counts = nxt

        return sum(counts) % MOD

