from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        lines = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def add(line, node, left, right):
            current = lines[node]
            if current is None:
                lines[node] = line
                return

            mid = (left + right) // 2
            if value(line, mid) > value(current, mid):
                lines[node], line = line, current

            if left == right:
                return
            if value(line, left) > value(lines[node], left):
                add(line, node * 2, left, mid)
            elif value(line, right) > value(lines[node], right):
                add(line, node * 2 + 1, mid + 1, right)

        def query(x, node, left, right):
            if lines[node] is None:
                result = -10**30
            else:
                result = value(lines[node], x)
            if left == right:
                return result
            mid = (left + right) // 2
            if x <= mid:
                return max(result, query(x, node * 2, left, mid))
            return max(result, query(x, node * 2 + 1, mid + 1, right))

        add((nums[0], 0), 1, 0, n - 1)
        answer = 0
        for j in range(1, n):
            answer = query(j, 1, 0, n - 1)
            add((nums[j], answer - j * nums[j]), 1, 0, n - 1)
        return answer

