class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        if all(x == 0 for x in nums):
            return 0

        # Bit s of reachable sums at index i after the processed prefix.
        reachable = [1] * n  # only sum 0 is initially reachable
        limits = [(1 << (x + 1)) - 1 for x in nums]

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                # This query can either be skipped or used once at index i.
                reachable[i] |= (reachable[i] << value) & limits[i]
            if all((reachable[i] >> nums[i]) & 1 for i in range(n)):
                return k
        return -1

