import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits

        prime = [True] * limit
        prime[0] = False
        prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                for v in range(p * p, limit, p):
                    prime[v] = False

        if prime[n] or prime[m]:
            return -1

        place_values = [10 ** i for i in range(digits)]
        infinity = 10 ** 30
        best = [infinity] * limit
        best[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != best[value]:
                continue
            if value == m:
                return cost

            for place in place_values:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if not prime[nxt] and cost + nxt < best[nxt]:
                        best[nxt] = cost + nxt
                        heapq.heappush(heap, (best[nxt], nxt))
                if digit > 0:
                    nxt = value - place
                    if not prime[nxt] and cost + nxt < best[nxt]:
                        best[nxt] = cost + nxt
                        heapq.heappush(heap, (best[nxt], nxt))

        return -1

