from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # dp[j] is LCP(nums[i:], nums[j:]) for the current i.
        dp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            for j in range(i + 1, n):
                dp[j] = 1 + dp[j + 1] if nums[i] == nums[j] else 0
                first = i <= j - i and z[i] >= i
                second = j - i <= n - j and dp[j] >= j - i
                if first or second:
                    answer += 1
        return answer

